'use client'

import { useState } from 'react'
import MainMenu from '@/components/MainMenu'
import BoutonFavori from '@/components/BoutonFavori'
import { useFavoris } from '@/hooks/useFavoris'
import { Globe, Instagram, ExternalLink, Download, Trash2, Heart, X } from 'lucide-react'
import { isNew } from '@/utils/helper'

export default function FavorisPage() {
  const { favoris, viderFavoris, exporterFavoris, count } = useFavoris()
  const [selectedLieu, setSelectedLieu] = useState(null)
  const [sortBy, setSortBy] = useState('recent') // 'recent', 'nom', 'ville'

  const TAG_COLORS = [
    "#9FFFCA", "#FFAEFF", "#FFAC88", "#C6BBFF", "#F9FFBD", "#A8FFD8",
    "#FC9F9F", "#FF8FD4", "#FFB7E3", "#FFB39A", "#FFD1B8", "#B8C7FF",
    "#D6D0FF", "#FFF3A0", "#EFFF9F", "#8FD6FF", "#AEE8FF", "#BFF2E8", "#FFDDEB",
  ]

  function getColorForType(type) {
    let hash = 0
    for (let i = 0; i < type.length; i++) {
      hash = type.charCodeAt(i) + ((hash << 5) - hash)
    }
    return TAG_COLORS[Math.abs(hash) % TAG_COLORS.length]
  }

  const favorisTries = [...favoris].sort((a, b) => {
    switch (sortBy) {
      case 'nom':
        return a.nom.localeCompare(b.nom)
      case 'ville':
        return a.ville.localeCompare(b.ville)
      case 'recent':
      default:
        return new Date(b.addedAt) - new Date(a.addedAt)
    }
  })

  return (
    <div className="min-h-screen bg-gray-50 p-4">
      {/* Sidebar lieu sélectionné */}
      {selectedLieu && (
        <div className="fixed right-0 top-0 h-full w-[90vw] max-w-[400px] bg-white shadow-2xl z-50 overflow-y-auto animate-slide-in">
          <div className="p-6">
            <div className="flex justify-between items-start mb-6">
              <div className="flex-1 pr-4">
                <div className="flex items-center gap-2 mb-2">
                  <h2 className="text-2xl font-bold text-gray-800">{selectedLieu.nom}</h2>
                  {isNew(selectedLieu.created_at) && (
                    <span className="bg-green-500 text-white text-xs font-bold px-2 py-1 rounded">
                      NOUVEAU
                    </span>
                  )}
                </div>
                <div className="flex flex-wrap gap-2 mb-2">
                  {selectedLieu.types.map(type => (
                    <span 
                      key={type}
                      style={{ backgroundColor: getColorForType(type), color: '#202020ff' }}
                      className="px-3 py-1 rounded-full text-sm"
                    >
                      {type}
                    </span>
                  ))}
                </div>
                <p className="text-gray-600">📍 {selectedLieu.ville}</p>
              </div>
              <button
                onClick={() => setSelectedLieu(null)}
                className="text-gray-400 hover:text-gray-600 p-2 transition-colors flex-shrink-0"
              >
                <X size={24} />
              </button>
            </div>

            {selectedLieu.description && (
              <div className="mb-6">
                <h3 className="font-semibold text-gray-700 mb-2">Description</h3>
                <p className="text-gray-600 leading-relaxed">{selectedLieu.description}</p>
              </div>
            )}

            {(selectedLieu.website || selectedLieu.instagram) && (
              <div className="space-y-3 mb-6">
                {selectedLieu.website && (
                  <a href={selectedLieu.website} target="_blank" rel="noopener noreferrer" className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors">
                    <Globe size={20} className="text-blue-600 flex-shrink-0" />
                    <span className="text-gray-700 font-medium">Voir le site web</span>
                    <ExternalLink size={16} className="text-gray-400 ml-auto flex-shrink-0" />
                  </a>
                )}
                
                {selectedLieu.instagram && (
                  <a href={selectedLieu.instagram.startsWith('http') ? selectedLieu.instagram : `https://instagram.com/${selectedLieu.instagram.replace('@', '')}`} target="_blank" rel="noopener noreferrer" className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors">
                    <Instagram size={20} className="text-pink-600 flex-shrink-0" />
                    <span className="text-gray-700 font-medium">Voir sur Instagram</span>
                    <ExternalLink size={16} className="text-gray-400 ml-auto flex-shrink-0" />
                  </a>
                )}
              </div>
            )}

            {/* Bouton retirer des favoris */}
            <div className="pt-6 border-t">
              <BoutonFavori lieu={selectedLieu} size={20} className="w-full justify-center" />
            </div>
          </div>
        </div>
      )}

      <div className="w-[95%] max-w-[95rem] mx-auto">
        {/* Header */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <div className="flex items-center gap-3 mb-2">
            <Heart className="text-red-500 fill-red-500" size={32} />
            <h1 className="text-3xl font-bold text-gray-800">Mes Favoris</h1>
          </div>
          <p className="text-gray-600 mb-4">
            {count === 0 
              ? "Vous n'avez pas encore de favoris. Explorez les lieux et ajoutez-les en cliquant sur le cœur ❤️" 
              : `${count} lieu${count > 1 ? 'x' : ''} sauvegardé${count > 1 ? 's' : ''}`
            }
          </p>
          <MainMenu />
        </div>

        {count > 0 && (
          <>
            {/* Barre d'actions */}
            <div className="bg-white rounded-lg shadow-sm p-4 mb-6 flex flex-wrap gap-3 items-center justify-between">
              <div className="flex items-center gap-2">
                <label className="text-sm font-medium text-gray-700">Trier par :</label>
                <select
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value)}
                  className="px-3 py-2 border rounded-lg text-sm focus:ring-2 focus:ring-blue-500"
                >
                  <option value="recent">Plus récents</option>
                  <option value="nom">Nom (A-Z)</option>
                  <option value="ville">Ville (A-Z)</option>
                </select>
              </div>

              <div className="flex gap-2">
                <button
                  onClick={exporterFavoris}
                  className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 flex items-center gap-2 text-sm font-medium"
                >
                  <Download size={18} />
                  Exporter
                </button>
                <button
                  onClick={viderFavoris}
                  className="bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700 flex items-center gap-2 text-sm font-medium"
                >
                  <Trash2 size={18} />
                  Tout supprimer
                </button>
              </div>
            </div>

            {/* Grille de favoris */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
              {favorisTries.map(lieu => (
                <div
                  key={lieu.id}
                  className="bg-white rounded-lg shadow-sm hover:shadow-md transition-shadow overflow-hidden group cursor-pointer"
                  onClick={() => setSelectedLieu(lieu)}
                >
                  <div className="p-5">
                    <div className="flex items-start justify-between mb-3">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <h3 className="font-bold text-gray-800 truncate">
                            {lieu.nom}
                          </h3>
                          {isNew(lieu.created_at) && (
                            <span className="bg-green-500 text-white text-xs font-bold px-1.5 py-0.5 rounded flex-shrink-0">
                              NEW
                            </span>
                          )}
                        </div>
                        <p className="text-sm text-gray-500 flex items-center gap-1">
                          📍 {lieu.ville}
                        </p>
                      </div>
                      <BoutonFavori lieu={lieu} size={20} />
                    </div>

                    <div className="flex flex-wrap gap-1.5 mb-3">
                      {lieu.types.slice(0, 3).map(type => (
                        <span 
                          key={type}
                          style={{ backgroundColor: getColorForType(type), color: '#202020ff' }}
                          className="px-2 py-1 rounded-full text-xs"
                        >
                          {type}
                        </span>
                      ))}
                      {lieu.types.length > 3 && (
                        <span className="px-2 py-1 rounded-full text-xs bg-gray-200 text-gray-600">
                          +{lieu.types.length - 3}
                        </span>
                      )}
                    </div>

                    {lieu.description && (
                      <p className="text-sm text-gray-600 line-clamp-2 mb-3">
                        {lieu.description}
                      </p>
                    )}

                    <div className="flex gap-2">
                      {lieu.website && (
                        <div className="flex items-center gap-1 text-xs text-blue-600">
                          <Globe size={14} />
                          <span>Site</span>
                        </div>
                      )}
                      {lieu.instagram && (
                        <div className="flex items-center gap-1 text-xs text-pink-600">
                          <Instagram size={14} />
                          <span>Insta</span>
                        </div>
                      )}
                    </div>

                    <div className="mt-3 pt-3 border-t text-xs text-gray-400">
                      Ajouté le {new Date(lieu.addedAt).toLocaleDateString('fr-FR')}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </>
        )}

        {/* État vide */}
        {count === 0 && (
          <div className="bg-white rounded-lg shadow-sm p-16 text-center">
            <div className="text-8xl mb-6">💔</div>
            <h2 className="text-2xl font-bold text-gray-700 mb-3">
              Aucun favori pour le moment
            </h2>
            <p className="text-gray-500 mb-6 max-w-md mx-auto">
              Parcourez les lieux dans la liste ou sur la carte et cliquez sur le cœur pour les ajouter à vos favoris !
            </p>
            <div className="flex gap-3 justify-center">
              <a 
                href="/"
                className="bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 font-medium"
              >
                Voir la liste
              </a>
              <a 
                href="/carte"
                className="bg-gray-200 text-gray-700 px-6 py-3 rounded-lg hover:bg-gray-300 font-medium"
              >
                Voir la carte
              </a>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}